pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum, uint256 lockTime, uint256 collectAmount) public {
        // restrict domain to feasible values
        vm.assume(minSum > 0);
        vm.assume(collectAmount > 0);
        vm.assume(lockTime > 0);
        // ensure arithmetic does not overflow reasonable amounts
        bound(minSum, 1, type(uint128).max);
        bound(lockTime, 1, type(uint64).max);
        bound(collectAmount, 1, type(uint128).max);

        // set up: attacker is a contract that re-enters through SetMinSum during Collect
        Attacker attacker = new Attacker();
        address attackerAddr = address(attacker);

        // initialize C
        c.Initialized();

        // set MinSum through re-entrant attacker
        vm.prank(attackerAddr);
        c.SetMinSum(minSum);

        // attacker deposits funds to satisfy balance >= MinSum and >= collectAmount
        vm.deal(attackerAddr, collectAmount + 1 ether);
        vm.prank(attackerAddr);
        c.Put{value: collectAmount}(lockTime);

        // warp past unlock time
        vm.warp(block.timestamp + lockTime + 1);

        // record MinSum before Collect
        uint256 minSumBefore = c.MinSum();

        // attacker calls Collect; its receive() re-enters SetMinSum with a new value
        attacker.setTarget(address(c));
        attacker.setCollectAmount(collectAmount);
        attacker.setNewMinSum(minSum + 1); // different value to overwrite
        vm.prank(attackerAddr);
        attacker.attack();

        // after Collect, MinSum should be unchanged (reference holds invariant); bug allows overwrite
        uint256 minSumAfter = c.MinSum();
        assertEq(minSumBefore, minSumAfter);
    }
}

contract Attacker {
    C target;
    uint256 collectAmount;
    uint256 newMinSum;

    function setTarget(address _target) external { target = C(_target); }
    function setCollectAmount(uint256 _amount) external { collectAmount = _amount; }
    function setNewMinSum(uint256 _newMinSum) external { newMinSum = _newMinSum; }

    function attack() external {
        target.Collect(collectAmount);
    }

    receive() external payable {
        // re-entrant call: override MinSum during Collect execution
        target.SetMinSum(newMinSum);
    }
}

