        //    the receive function that attempts to overwrite MinSum via SetMinSum.
        vm.expectEmit(true, true, true, true);
        try c.Collect(1 ether) {
            // If the call succeeds (it will in both versions unless something reverts),
            // we check the invariant.
        } catch {
            // If Collect reverts, the invariant may also hold; we still check
        }

