pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Reverter reverter;

    function setUp() public {
        c = new C();
        reverter = new Reverter();
    }

    function testFuzz_property(uint256 minSumBefore, uint256 minSumNew) public {
        // Set up the contract in initialized state with a given MinSum
        c.SetMinSum(minSumBefore);
        c.Initialized();
        // Remember the MinSum before the no-op call
        uint256 expectedMinSum = c.MinSum();
        // The no-op call to SetMinSum must not change MinSum
        c.SetMinSum(minSumNew);
        // Now trigger a Collect that will call the reverter, causing the external call to fail
        // We need to ensure the holder has enough balance and unlockTime is passed.
        vm.deal(address(this), minSumBefore + 1);
        vm.warp(1000);
        c.Put{value: minSumBefore + 1}(0);
        vm.warp(2000);
        // Collect with an amount that triggers the external call to the reverter
        c.Collect(minSumBefore / 2 + 1);
        // After the failed external call, MinSum must still be the expected value
        assertEq(c.MinSum(), expectedMinSum, "MinSum changed after Collect via failing callee");
    }
}

