import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _val) public {
        // _val is in the admissible domain for MinSum; keep the input space wide.
        // The reference contract requires initialization before SetMinSum can succeed:
        // Setting LogFile and calling Initialized.
        vm.prank(address(1));
        c.SetLogFile(address(0xdead));
        vm.prank(address(1));
        c.Initialized();

        // Now call the unit under test.
        vm.prank(address(1));
        c.SetMinSum(_val);

        // Property: MinSum must equal the supplied _val (the reference stores it;
        // the mutant body does nothing, so MinSum remains 0).
        assertEq(c.MinSum(), _val, "MinSum should equal the supplied value");
    }
}

