pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract ReentrantSetter {
    C target;
    address newLog;
    uint8 count;
    constructor(C _target, address _newLog) {
        target = _target;
        newLog = _newLog;
    }
    fallback() external payable {
        if (count < 2) {
            count++;
            target.SetLogFile(newLog);
        }
    }
}

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address log, address attackerPayable, uint256 _lockTime) public {
        // Ensure addresses are not null
        vm.assume(log != address(0));
        vm.assume(attackerPayable != address(0) && log != address(c) && attackerPayable != address(c));

        // Initialize the contract
        c.SetMinSum(0);
        c.SetLogFile(log);
        c.Initialized();

        // Deploy a reentrant attacker that will call SetLogFile again during LogFile.AddMessage
        address attacker = address(new ReentrantSetter(c, attackerPayable));

        // Attacker deposits ether to trigger Put, which calls LogFile.AddMessage
        // During AddMessage, the reentrant contract tries to call SetLogFile again.
        vm.deal(attacker, 1 ether);
        vm.prank(attacker);
        (bool success,) = address(c).call{value: 0.1 ether}("");

        // Property: The LogFile address must remain unchanged equal to the initial log address.
        // The reference contract's nonReentrant modifier prevents reentrancy, so LogFile remains log.
        // The buggy contract allows reentrant modification, so LogFile becomes attackerPayable.
        assertEq(address(c.LogFile()), log);
    }
}
